import { Component, createMemo, createSignal, Show } from "solid-js";

import ContextManager from "#core/ui/context-manager/context-manager.js";
import { GameCreatorClosedEvent, StartCampaignEvent } from "#core/ui/events/shell-events.js";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { Popup, PopupContextProvider } from "#core/ui-next/components/popup.jsx";
import {
	ScreenFlowContextProvider,
	ScreenFlowScreen,
	ScreenFlowStepType,
	ScreenFlowTab,
	useScreenFlowContext,
} from "#core/ui-next/components/screen-flow.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { NestedTooltipContext } from "#core/ui-next/components/tooltip-compat.jsx";
import { AdvancedOptionsScreen } from "#core/ui-next/screens/create-game/advanced-options.jsx";
import { AgeSelectModel, AgeSelectModelContext } from "#core/ui-next/screens/create-game/age-select-model.js";
import { AgeSelectPopup } from "#core/ui-next/screens/create-game/age-select-popup.jsx";
import { CivDetails } from "#core/ui-next/screens/create-game/civ-details.jsx";
import { CivSelectModel, CivSelectModelContext } from "#core/ui-next/screens/create-game/civ-select-model.js";
import { CivSelectScreen } from "#core/ui-next/screens/create-game/civ-select-screen.jsx";
import { CreateGameHub } from "#core/ui-next/screens/create-game/create-game-hub.jsx";
import { GameSetupModel, GameSetupModelContext } from "#core/ui-next/screens/create-game/create-game-setup-model.js";
import { CreateGameSetup } from "#core/ui-next/screens/create-game/create-game-setup.jsx";
import { LeaderPedestalBanner3d } from "#core/ui-next/screens/create-game/leader-banner-3d.jsx";
import { LeaderSelectModel, LeaderSelectModelContext } from "#core/ui-next/screens/create-game/leader-select-model.js";
import { LeaderSelectScreen } from "#core/ui-next/screens/create-game/leader-select-screen.jsx";
import { MapSelect } from "#core/ui-next/screens/create-game/map-select.jsx";
import {
	MementoSelectModel,
	MementoSelectModelContext,
} from "#core/ui-next/screens/create-game/memento-select-model.js";
import { MementoSelect } from "#core/ui-next/screens/create-game/memento-select.jsx";
import {
	RecommendedChoiceModel,
	RecommendedChoiceModelContext,
} from "#core/ui-next/screens/create-game/recommended-choice-model.js";
import { TotModel, TotModelContext } from "#core/ui-next/screens/create-game/tot-model.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { LayoutModel } from "#core/ui-next/utilities/layout-utilities.js";

// Stays mounted across game-setup <-> create-game-hub transitions so the
// engine ModelGroup is not destroyed and re-created on every screen switch.
const PersistentPedestalBanner: Component = () => {
	const flow = useScreenFlowContext();
	const layout = LayoutModel.get();

	const visible = createMemo(() => {
		const active = flow.active()?.name;
		if (active === "create-game-hub") return true;
		if (active === "game-setup") return !(layout.screenHeight() <= 1000 && layout.screenWidth() < 1600);
		return false;
	});

	return (
		<Show when={visible()}>
			<LeaderPedestalBanner3d />
		</Show>
	);
};

export interface CreateGameScreenProps {
	screenFlow: ScreenFlowScreen[];
}

const CreateGameScreenComponent: Component<CreateGameScreenProps> = (props) => {
	const ageSelectModel = AgeSelectModel.get();
	const civSelectModel = CivSelectModel.get();
	const leaderSelectModel = LeaderSelectModel.get();
	const gameSetupModel = GameSetupModel.get();
	const totModel = TotModel.get();
	const mementoModel = MementoSelectModel.get();
	const choiceModel = RecommendedChoiceModel.get();
	const [popupContext, setPopupContext] = createSignal<PopupContextProvider>();
	let flowContextRef: ScreenFlowContextProvider;

	function closeScreen() {
		// back to main menu
		ContextManager.popUntil("main-menu");
		window.dispatchEvent(new GameCreatorClosedEvent());
	}

	function handleCancelInput() {
		if (popupContext()?.active()) {
			popupContext()?.close();
		} else {
			if (flowContextRef?.active()?.name == "create-game-hub") {
				flowContextRef?.clearHub();
			}

			if (flowContextRef?.active()?.name == "game-setup" && civSelectModel.selectedCiv().civID == "RANDOM") {
				flowContextRef?.activate("civ-select");
			} else {
				flowContextRef?.activatePrev();
			}
		}
		useAudio("CreateGameBackButton")("activate");
	}

	function launchGame() {
		window.dispatchEvent(new StartCampaignEvent());
		engine.call("startGame");
	}

	return (
		<Panel
			id="create-game"
			name="create-game"
			class="fullscreen"
			onCancelInput={handleCancelInput}
		>
			<NestedTooltipContext.Provider value={{ disabled: true }}>
				<GameSetupModelContext.Provider value={gameSetupModel}>
					<AgeSelectModelContext.Provider value={ageSelectModel}>
						<CivSelectModelContext.Provider value={civSelectModel}>
							<LeaderSelectModelContext.Provider value={leaderSelectModel}>
								<TotModelContext.Provider value={totModel}>
									<MementoSelectModelContext.Provider value={mementoModel}>
										<RecommendedChoiceModelContext.Provider value={choiceModel}>
											<Popup setPopupContext={setPopupContext}>
												<ScreenFlowTab
													class="fullscreen"
													defaultTab={props.screenFlow[0].name}
													screens={props.screenFlow}
													onClose={closeScreen}
													onStart={launchGame}
													contextRef={(ref) => {
														flowContextRef = ref;
													}}
												>
													<Tab.Output />
													<PersistentPedestalBanner />
													<Tab.Item
														name="create-game-hub"
														title={() => null}
														body={() => <CreateGameHub />}
													/>
													<Tab.Item
														name="game-setup"
														title={() => null}
														body={() => <CreateGameSetup />}
													/>
													<Tab.Item
														name="civ-select"
														title={() => null}
														body={() => <CivSelectScreen />}
													/>
													<Tab.Item
														name="civ-details"
														title={() => null}
														body={() => <CivDetails />}
													/>
													<Tab.Item
														name="leader-select"
														title={() => null}
														body={() => <LeaderSelectScreen />}
													/>
													<Tab.Item
														name="memento-select"
														title={() => null}
														body={() => <MementoSelect />}
													/>
													<Popup.Item name="age-select">
														<AgeSelectPopup />
													</Popup.Item>
													<Popup.Item name="advanced-options">
														<AdvancedOptionsScreen />
													</Popup.Item>
													<Popup.Item name="map-select">
														<MapSelect />
													</Popup.Item>
												</ScreenFlowTab>
												<Popup.Output class="fullscreen child-fullscreen" />
											</Popup>
										</RecommendedChoiceModelContext.Provider>
									</MementoSelectModelContext.Provider>
								</TotModelContext.Provider>
							</LeaderSelectModelContext.Provider>
						</CivSelectModelContext.Provider>
					</AgeSelectModelContext.Provider>
				</GameSetupModelContext.Provider>
			</NestedTooltipContext.Provider>
		</Panel>
	);
};

export const CreateGameScreen = ComponentRegistry.register("create-game-screen", CreateGameScreenComponent);

defineLegacyComponent("create-game-sp", { classNames: ["fullscreen"] }, () => {
	Input.setActiveContext(InputContext.Shell);
	return (
		<CreateGameScreen
			screenFlow={[
				{ name: "leader-select", step: "leader-select", type: ScreenFlowStepType.Start },
				{ name: "civ-select", step: "civ-select" },
				{ name: "civ-details", step: "civ-select" },
				{ name: "game-setup", step: "game-setup" },
				{ name: "create-game-hub", type: ScreenFlowStepType.Hub },
				{ name: "memento-select" },
			]}
		/>
	);
});
